import math

def z1(y):
    val = 8*y - math.sqrt(28*y**2 + 12)
    return val / 6

def z2(y):
    val = 8*y + math.sqrt(28*y**2 + 12)
    return val / 6

def h_n(y, n):
    # h_n(y) = z1(z1(...z1(z2(z2(...z2(y)...))))) with (n-1) z1s and (n-1) z2s
    res = y
    for _ in range(n-1):
        res = z2(res)
    for _ in range(n-1):
        res = z1(res)
    return res

for n in range(2, 10):
    found = False
    for y in [0.1, 1, 10, 100, 1000, 10000]:
        if h_n(y, n) >= y:
            print(f"n={n}, y={y}, h_n={h_n(y, n)}")
            found = True
            break
    if not found:
        print(f"n={n} not possible for these y")

